-- Class notes synopsis batch 16: Lily Of The Valley through Marjoram

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Lily of the Valley</strong> is a <strong>cardiac medicinal</strong> used at <strong>super low dose</strong>, similar in action to <strong>Foxglove</strong>; its flower essence connects to the angel realm. <strong>Extremely toxic at higher doses - using in perfumery risks stopping someone's heart; super low dose only.</strong>$$
WHERE id = 163;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Linden</strong> is a <strong>hypotensive</strong>, <strong>calming nervine</strong>, <strong>demulcent</strong>, and <strong>spirit remedy</strong>; heart-shaped leaves reflect its affinity for the <strong>cardiovascular</strong> system and emotional body - highlighted as the herb to "work with the most" for cardiovascular support; a versatile herb that "can do a lot of things." Specific for <strong>white coat hypertension</strong> (anxiety-induced elevated BP); for <strong>nerves causing cardiovascular heat and palpitations</strong>; hypotensive - use semi-preventatively when BP starts to creep up - not in acute conditions; added when patient found to have undiagnosed elevated BP at the cusp of type II diabetes. <strong>Relaxing nervine</strong> for <strong>anxiety</strong>; a grief remedy - <strong>spirit remedy</strong> for processing grief, "tree of joy and sorrow"; modulator of emotions (lowers excess or raises deficiency); pairs with <a href="?herb=134"><strong>Lemon Balm</strong></a> and <strong>Mimosa</strong> flowers for <strong>depression</strong>; astringent quality can ground weepiness; for <strong>children who can't sleep</strong>. Mood support in <strong>chemical sensitivity</strong> formulas (drowsiness caution - adjust for balance); in <strong>PCOS</strong> formulas; specifically highlighted for <strong>stroke</strong> support: "important to calm the person down, accept what happened." Preparation: a short infusion (few minutes) makes it <strong>astringent</strong>; a long infusion (few hours) shifts it to <strong>demulcent</strong>; mucilage extracted via cold water; prefer glycerites, honeys, or vinegars over alcohol for GI use; for <strong>common cold sore throat</strong> as demulcent. Heart Formula glycerite - helps the body restart natural BP regulation after pharmaceutical medication wears off at midday - with <a href="?herb=73"><strong>Hawthorn</strong></a> L+F, <a href="?herb=131"><strong>Motherwort</strong></a>, possibly <a href="?herb=13"><strong>Holy Basil</strong></a>; glycerite tonic with <a href="?herb=178"><strong>Milky Oats</strong></a>, <a href="?herb=73"><strong>Hawthorn</strong></a>, <a href="?herb=852"><strong>Shatavari</strong></a>, <a href="?herb=2229"><strong>Gotu Kola</strong></a>, <a href="?herb=2653"><strong>Bleeding Heart</strong></a>, <a href="?herb=25"><strong>Black Cohosh</strong></a>; in <a href="?herb=84"><strong>Chamomile</strong></a>/Linden/<a href="?herb=76"><strong>Fennel</strong></a> glycerite for post-menopausal poor sleep and restlessness. Daily Tea blend: 5p <a href="?herb=45"><strong>Marshmallow</strong></a> leaf, 4p <a href="?herb=61"><strong>Mullein</strong></a>, 3p Linden, 2p <a href="?herb=850"><strong>Rose</strong></a>, 1p <a href="?herb=167"><strong>Cinnamon</strong></a>. Use teas for hydration with <a href="?herb=45"><strong>Marshmallow</strong></a> and <a href="?herb=167"><strong>Cinnamon</strong></a>. <strong>Caution: can lower BP too much in patients on multiple blood pressure medications (e.g., Losartan, Hydralazine, Lasix) - do NOT take simultaneously with BP pharmaceuticals; BP could go too low; start with small tea doses at midday; taper slowly to get off the drug.</strong>$$
WHERE id = 90;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Lion's Mane Mushroom</strong> is a <strong>power herb</strong> for <strong>cognitive support</strong> - for presentations like "standing in the kitchen not knowing what to do"; <strong>regenerates nerves</strong> and influences cognition; used for <strong>concussion</strong> support; provides <strong>pre-biotic fiber</strong> and <strong>immune modulation</strong>. Among the mushrooms, <a href="?herb=2634"><strong>Cordyceps</strong></a> is more about energy while Lion's Mane and <a href="?herb=11"><strong>Reishi Mushroom</strong></a> are more about focus.$$
WHERE id = 2632;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Lobelia</strong> (Indian tobacco) is the key <strong>antispasmodic</strong> and <strong>bronchodilator</strong> in the respiratory materia medica - relaxes bronchial structures and opens capillaries to allow more expectorant efficacy; specific for <strong>asthma</strong>, <strong>anaphylaxis</strong>, and <strong>emphysema</strong> (pulmonary tonic); a <strong>relaxing expectorant</strong> for hot/damp cough; also dilates other structures such as the <strong>cervix</strong>. A <strong>nervine</strong> and <strong>muscle relaxant</strong> for musculoskeletal excess; increases parasympathetic function in <strong>respiratory deficiency</strong> at small doses; in Thompson's Standard Protocol to stimulate digestion (purging - elimination of waste); used in <strong>cancer</strong> blood-cleansing tonic formula. Alkaloidal plant - requires 5-10% vinegar when tincturing. Simple tincture (separate from base formula): 5 drops low dose, near full cap for acute asthma attack; maintenance dose 5-30 drops paired with full formula for ongoing support. <strong>Emetic (not antiemetic) at high doses; acrid, slightly toxic; can cause vomiting at high doses; use as drop or low dose only.</strong>$$
WHERE id = 132;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Lomatium</strong> is the most potent <strong>antiviral</strong> in the <strong>respiratory</strong> materia medica - inhibits viral replication; a <strong>stimulating expectorant</strong> for cold/damp cough (warming and drying). <strong>Can be so effective that viral shedding pushes waste out through the skin as a rash - start low and be careful with dosing.</strong>$$
WHERE id = 980;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Ma Huang</strong> (Ephedra) is a <strong>bronchodilator</strong>, <strong>antispasmodic</strong>, and <strong>decongestant</strong> used for <strong>asthma</strong>, <strong>allergic reactions</strong>, and <strong>emphysema</strong>.$$
WHERE id = 448;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Maca</strong> is a <strong>warming</strong> adaptogen and <strong>libido enhancer</strong> for <strong>sex hormone regulation</strong> - listed alongside <a href="?herb=20"><strong>Ashwagandha</strong></a> (yang tonic) and the Ginsengs as adaptogens for hormonal support; an <strong>aphrodisiac</strong> herb for <strong>erectile dysfunction</strong>.$$
WHERE id = 851;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Maitake</strong> (Grifola frondosa) is an <strong>adaptogen</strong> and <strong>immune tonic</strong>; one of the best mushrooms for <strong>diabetes</strong> - regulates <strong>blood sugar</strong> and good for <strong>insulin resistance</strong> at high dose (capsule or powdered extract); indicated to induce <strong>ovulation</strong> in <strong>PMOS</strong>; for <strong>influenza</strong> immune support - use after the acute phase resolves.$$
WHERE id = 2633;

